/**
 * Parses the `cart` query parameter used by shareable pre-filled checkout
 * links, e.g.
 *
 *   /store/checkout?cart=festival-ticket-full:2,endemit-vinyl-vol1&code=FRIENDS20
 *
 * Format: comma-separated product uids, each with an optional `:quantity`
 * suffix that defaults to 1. Chosen so a link can be composed and read by
 * hand, which is the whole point — these are pasted into messages and
 * encoded into QR codes by people, not generated by code.
 *
 * Parsing is deliberately forgiving: the parameter comes from a URL that may
 * have been hand-edited or truncated by a messaging app, so an unusable entry
 * is skipped rather than failing the whole link and leaving the customer on a
 * broken checkout. Whether a uid actually exists is a separate question,
 * answered against the CMS by the caller.
 */

/** Guards against a hand-edited link ordering an absurd quantity. */
const MAX_QUANTITY_PER_LINE = 99;

/** Guards against a pathologically long URL producing a huge cart. */
const MAX_LINES = 20;

export interface CartPrefillItem {
  uid: string;
  quantity: number;
}

export function parseCartPrefill(
  cartParam: string | null | undefined
): CartPrefillItem[] {
  if (!cartParam) return [];

  const items: CartPrefillItem[] = [];
  const seen = new Map<string, number>();

  for (const rawEntry of cartParam.split(",")) {
    if (seen.size >= MAX_LINES) break;

    const entry = rawEntry.trim();
    if (!entry) continue;

    // Only the first colon separates uid from quantity; a uid never contains
    // one, so anything after a second colon is malformed input to ignore.
    const [rawUid, rawQuantity] = entry.split(":");
    const uid = rawUid?.trim().toLowerCase();
    if (!uid) continue;

    let quantity = 1;
    if (rawQuantity !== undefined) {
      const parsed = Number.parseInt(rawQuantity.trim(), 10);
      // A malformed or non-positive quantity falls back to 1 rather than
      // dropping the product the sender clearly intended to include.
      if (Number.isFinite(parsed) && parsed > 0) {
        quantity = Math.min(parsed, MAX_QUANTITY_PER_LINE);
      }
    }

    // The same uid repeated in one link accumulates, matching what adding it
    // twice in the shop would do.
    const existingIndex = seen.get(uid);
    if (existingIndex !== undefined) {
      items[existingIndex].quantity = Math.min(
        items[existingIndex].quantity + quantity,
        MAX_QUANTITY_PER_LINE
      );
      continue;
    }

    seen.set(uid, items.length);
    items.push({ uid, quantity });
  }

  return items;
}

/** Normalizes the `code` query parameter. Discount codes are stored upper. */
export function parseDiscountCodeParam(
  codeParam: string | null | undefined
): string | undefined {
  if (!codeParam) return undefined;
  const code = codeParam.trim().toUpperCase();
  // Codes are alphanumeric with dashes/underscores; reject anything else
  // rather than round-tripping junk through the validation endpoint.
  if (!code || !/^[A-Z0-9_-]{1,64}$/.test(code)) return undefined;
  return code;
}
